package Custom_Fixed_Point is

   D : constant := 2.0 ** (-15);
   type Short_Fixed is
     delta D
     range -1.0 .. 1.0 - D;

   subtype Coefficient is Short_Fixed
     range 0.0 .. 1.0 - D;

end Custom_Fixed_Point;

with Ada.Text_IO; use Ada.Text_IO;

with Custom_Fixed_Point;
use  Custom_Fixed_Point;

procedure Show_Fixed_Point_Subtypes is
   SF : Short_Fixed;
   C  : Coefficient;
begin
   SF := 0.25;
   Put_Line ("SF = "
             & SF'Image);

   C := SF;
   Put_Line ("C  = "
             & C'Image);
   Put_Line ("---------");

   SF := -0.25;
   Put_Line
     ("SF in Short_Fixed: "
      & Boolean'Image
          (SF in Short_Fixed));
   Put_Line
     ("SF in Coefficient: "
      & Boolean'Image
          (SF in Coefficient));
end Show_Fixed_Point_Subtypes;
